import{_ as e,c as o,o as t,a3 as d}from"./chunks/framework.Bsyxd66g.js";const m=JSON.parse('{"title":"Web UI","description":"","frontmatter":{},"headers":[],"relativePath":"subsystems/web-ui.md","filePath":"subsystems/web-ui.md","lastUpdated":1794137243000}'),s={name:"subsystems/web-ui.md"},i=d('<h1 id="web-ui" tabindex="-1">Web UI <a class="header-anchor" href="#web-ui" aria-label="Permalink to &quot;Web UI&quot;">​</a></h1><h2 id="responsibility-and-boundaries" tabindex="-1">Responsibility and boundaries <a class="header-anchor" href="#responsibility-and-boundaries" aria-label="Permalink to &quot;Responsibility and boundaries&quot;">​</a></h2><ul><li>Owns: the SvelteKit single-page admin app under <code>web/</code> — routes, navigation, the API client, the WebSocket client, status/segment rendering, filter state, settings forms (including notifier editing, Bilibili QR login, danmaku milestones) and the build artifacts embedded into the binary.</li><li>Does not own: endpoint semantics and JSON contracts (<a href="./web-api-server">web-api-server.md</a>); server-side rules for status bits (<a href="./sync-pipeline">sync-pipeline.md</a>); configuration validation (<a href="./config-and-persistence">config-and-persistence.md</a>); notification delivery (<a href="./notifications">notifications.md</a>).</li><li>Talks to: <code>/api</code> over <code>fetch</code> and <code>/api/ws</code> over a native <code>WebSocket</code>; persists only the auth token in <code>localStorage[&#39;authToken&#39;]</code>.</li></ul><h2 id="sources-of-truth" tabindex="-1">Sources of truth <a class="header-anchor" href="#sources-of-truth" aria-label="Permalink to &quot;Sources of truth&quot;">​</a></h2><ul><li>Authoritative routes and screens: <code>web/src/routes/</code> (<code>+layout.svelte</code>, <code>+layout.ts</code>, <code>+page.svelte</code>, <code>logs/</code>, <code>videos/</code>, <code>video/[id]/</code>, <code>video-sources/</code>, <code>settings/</code>, <code>me/favorites</code>, <code>me/collections</code>, <code>me/uppers</code>).</li><li>Authoritative navigation: <code>web/src/lib/components/app-sidebar.svelte</code> (<code>navMain</code>, <code>footer</code>).</li><li>Authoritative API surface: <code>web/src/lib/api.ts</code> (<code>ApiClient</code>, <code>apiClient</code>, the <code>api</code> convenience object) and <code>web/src/lib/types.ts</code>.</li><li>Authoritative socket protocol: <code>web/src/lib/ws.ts</code> (<code>EventType</code>, <code>WebSocketManager</code>, <code>wsManager</code>).</li><li>Authoritative filter state: <code>web/src/lib/stores/filter.ts</code> (<code>AppState</code>, <code>appStateStore</code>, <code>ToQuery</code>, <code>ToFilterParams</code>).</li><li>Authoritative status labels: <code>web/src/lib/components/status-editor.svelte</code> (<code>videoTaskNames</code>, <code>pageTaskNames</code>) and <code>web/src/lib/components/video-card.svelte</code> (<code>getStatusText</code>, <code>getOverallStatus</code>).</li><li>Forbidden duplicate sources: a second fetch wrapper, hand-written endpoint strings outside <code>api.ts</code>, or status label lists diverging between <code>status-editor.svelte</code> and <code>video-card.svelte</code>.</li></ul><h2 id="main-paths-change-loci" tabindex="-1">Main paths / change loci <a class="header-anchor" href="#main-paths-change-loci" aria-label="Permalink to &quot;Main paths / change loci&quot;">​</a></h2><ul><li>Key entry points: <ul><li><code>web/src/routes/+layout.ts</code> (<code>ssr = false</code>, <code>prerender = false</code>) and <code>web/src/routes/+layout.svelte</code> (sidebar + header + <code>#main</code> scroll container).</li><li><code>web/src/lib/api.ts</code> (<code>ApiClient.request</code>, <code>setAuthToken</code>, <code>getAuthToken</code>, <code>clearAuthToken</code>, the <code>subscribeTo*</code> helpers).</li><li><code>web/src/lib/ws.ts</code> (<code>WebSocketManager.connect</code>, <code>subscribe</code>, <code>scheduleReconnect</code>, <code>disconnect</code>).</li></ul></li><li>Common edit locations: <ul><li>New screen: add a route directory under <code>web/src/routes/</code> and a sidebar entry in <code>app-sidebar.svelte</code>.</li><li>New API call: method on <code>ApiClient</code>, re-export in the <code>api</code> object, type in <code>web/src/lib/types.ts</code>.</li><li>New event type: <code>EventType</code> in <code>ws.ts</code>, plus the server side in <code>api/routes/ws/mod.rs</code>.</li><li>Status semantics/labels: <code>status-editor.svelte</code> + <code>video-card.svelte</code> together with <code>utils/status.rs</code>.</li><li>Dev proxy target: <code>web/vite.config.ts</code>.</li></ul></li><li>Routes present: <ul><li><code>/</code> dashboard: <code>getDashboard()</code> returns the 5 most-recently-added videos (<code>recent_videos</code>, ordered by <code>created_at</code>/<code>id</code> desc) shown as compact cards with <code>created_at</code> rendered as 月-日 时:分 in the browser&#39;s local timezone (the SQLite value is a naive UTC string parsed with an appended <code>Z</code>); shares <code>subscribeToSysInfo</code>/<code>subscribeToTasks</code>/<code>subscribeToLogs</code>. No history charts for CPU/memory (tokens only); the logs card keeps the last 10 lines newest-first via <code>pushLog</code> in <code>$lib/dashboard-data.ts</code>; layout stacks on mobile and puts 最近入库/最新日志 side by side from <code>lg</code>; triggers <code>POST /api/task/download</code> via <code>triggerDownloadTask</code>.</li><li><code>/logs</code>: subscribes to logs and keeps the last 500 entries (<code>logs.slice(-499)</code>), auto-scrolls unless the user scrolled up.</li><li><code>/videos</code>: list with URL-synced filters (page size 20), source/query/status/validation/created-time filters, single-video redownload; video deletion and cleanup are not exposed. Covers and titles open details; a cover-corner icon displays status.</li><li><code>/organization</code>: create, edit and copy TV or movie rules; browse server directories or enter paths (the directory picker invalidates stale listings using a <code>requestSeq</code> token); preview the plan and select movies, or run a rule directly from the list. Direct movie execution previews candidates and submits executable video IDs; results show counts and warnings.</li><li><code>/video/[id]</code>: detail, per-subtask status editor, reset (optional <code>force</code>), without the destructive clear-and-reset action.</li><li><code>/video-sources</code>: tabs for favorites/collections/submissions/watch_later; add/update/remove/evaluate/full-sync; new items are created disabled.</li><li><code>/settings</code>: token authentication bar, config tabs (basic/auth/filter/danmaku/notifiers/advanced), notifier CRUD + test, QR login dialog.</li><li><code>/me/favorites</code>, <code>/me/collections</code>, <code>/me/uppers</code>: followed/subscribed lists, with 1-based <code>page_num</code> for collections and uppers.</li></ul></li></ul><h2 id="runtime-paths-and-state-transitions" tabindex="-1">Runtime paths and state transitions <a class="header-anchor" href="#runtime-paths-and-state-transitions" aria-label="Permalink to &quot;Runtime paths and state transitions&quot;">​</a></h2><ul><li>Trigger / inputs / outputs / interfaces: <ul><li>Build: <code>vite build</code> produces <code>web/build</code>, which <code>task/http_server.rs</code> embeds via <code>#[folder = &quot;../../web/build&quot;]</code>. The app is fully client-side (<code>ssr = false</code>, <code>prerender = false</code>, adapter-static with <code>fallback: &#39;index.html&#39;</code>).</li><li>Runtime inputs: HTTP JSON from <code>/api</code>, WebSocket events, <code>localStorage[&#39;authToken&#39;]</code>.</li><li>Runtime outputs: rendered screens, toasts (<code>svelte-sonner</code>), mutations through the API.</li></ul></li><li>Main execution path (source files and named symbols): <ol><li><code>ApiClient</code> is constructed at module load with <code>API_BASE_URL = &#39;/api&#39;</code>, <code>Content-Type: application/json</code>, and <code>Authorization</code> taken from <code>localStorage[&#39;authToken&#39;]</code>. <code>request()</code> serializes defined query parameters, JSON-encodes non-GET bodies, and maps any non-2xx response to <code>{ message, status }</code> by reading <code>message</code>/<code>error</code> from the JSON body.</li><li><code>setAuthToken</code> stores the token and header; <code>clearAuthToken</code> deletes both and calls <code>wsManager.disconnect()</code>. Authentication is entered in <code>/settings</code> (the &quot;前端认证状态&quot; bar), which then reloads the config to prove the token works.</li><li><code>WebSocketManager</code> is a singleton. <code>connect()</code> builds <code>${ws|wss}://${location.host}/api/ws</code> and passes the token as the subprotocol: <code>btoa(token)</code> with <code>+</code>→<code>-</code>, <code>/</code>→<code>_</code>, padding stripped (matching the server&#39;s <code>BASE64_URL_SAFE_NO_PAD</code>). On open it re-subscribes every event in <code>subscribedEvents</code>.</li><li>Subscription is reference-counted by callback sets: the first subscriber for an event sends <code>{&quot;subscribe&quot;: &quot;&lt;event&gt;&quot;}</code>, the last unsubscriber sends <code>{&quot;unsubscribe&quot;: &quot;&lt;event&gt;&quot;}</code>. Incoming frames are parsed as <code>{ logs?, tasks?, sysInfo? }</code> and fanned out to the matching callback set; a parse failure shows a toast.</li><li>Reconnection: on <code>close</code>, <code>scheduleReconnect</code> retries indefinitely with exponential delays capped at 30 seconds; an explicit <code>disconnect()</code> stops retries and clears subscriptions.</li><li>Filter state lives in <code>appStateStore</code> (defaults <code>validationFilter: &#39;normal&#39;</code>, <code>currentPage: 0</code>); <code>ToQuery</code> maps it to URL parameters (<code>page</code>, <code>query</code>, <code>&lt;sourceType&gt;</code>, <code>status_filter</code>, <code>validation_filter</code>, <code>created_from</code>, <code>created_to</code>) and <code>ToFilterParams</code> to API parameters, so filtered views are shareable/reloadable.</li><li>Status rendering: the API returns <code>download_status</code> as five numbers. <code>getStatusText</code> renders <code>7</code> → 已完成, <code>0</code> → 未开始, else 失败N次; <code>getOverallStatus</code> prioritizes <code>!valid</code> → 失效, <code>!should_download</code> → 跳过, all-7 → 完成, any-not-7-not-0 → 失败, else 等待. The editor only allows setting 0 or 7, and resetting page status forces the video&#39;s index 4 (&quot;分页下载&quot;) to 0 on the server.</li><li>Video cards load downloaded covers through an authenticated fetch and reference-counted object URLs (<code>video-cover.svelte</code>, <code>cover-cache.ts</code>); missing covers show a placeholder. Organization dialogs use the rule and preview APIs.</li><li>Settings forms: <code>intervalInput</code> is parsed on save — a purely numeric string becomes a number (<code>Trigger::Interval</code>), anything else a string (<code>Trigger::Cron</code>). Notifier dialog fields mirror <code>Notifier</code> (telegram/webhook/smtp); SMTP defaults to port 465 and <code>tls</code>. The QR dialog polls <code>GET /api/login/qrcode/poll</code> every 2 seconds with a 180-second expiry.</li></ol></li><li>State ownership, transitions and persistence: <ul><li>The only persisted client state is <code>localStorage[&#39;authToken&#39;]</code>; everything else is in-memory and lost on reload.</li><li>The socket&#39;s <code>subscribedEvents</code> set is cleared by <code>disconnect()</code> and replayed after reconnect.</li><li>No optimistic updates for the config: <code>updateConfig</code> replaces <code>formData</code> with the server response, so a rejected save leaves the previous values visible.</li></ul></li></ul><h2 id="constraints-and-failures" tabindex="-1">Constraints and failures <a class="header-anchor" href="#constraints-and-failures" aria-label="Permalink to &quot;Constraints and failures&quot;">​</a></h2><ul><li>Invariants: <ul><li>JSON requests go through <code>api.ts</code>; it owns the base URL, token header and error normalization. Local cover image fetches use the same authentication token via the cover cache.</li><li>The socket URL must stay on the same origin (<code>/api/ws</code>) so the embedded build works behind any reverse proxy; only the protocol follows <code>location.protocol</code>.</li><li><code>download_status</code> is always treated as a five-element array; never as a bitfield in the UI.</li><li>Task labels must match the backend offsets: video <code>[&#39;视频封面&#39;,&#39;视频信息&#39;,&#39;UP 主头像&#39;,&#39;UP 主信息&#39;,&#39;分页下载&#39;]</code>, page <code>[&#39;视频封面&#39;,&#39;视频内容&#39;,&#39;视频信息&#39;,&#39;视频弹幕&#39;,&#39;视频字幕&#39;]</code>.</li></ul></li><li>Failure modes and recovery: <ul><li>401 from any call surfaces as <code>{message: &#39;auth token does not match&#39;, status: 401}</code>; the user re-enters the token in <code>/settings</code>. There is no global interceptor — each page shows a toast.</li><li>A lost WebSocket degrades to exponential retries with a 30-second delay cap until the connection recovers.</li><li>A failed save (validation or version mismatch) shows the server <code>message</code> and keeps the form values; the user must reload to pick up <code>version</code> changes.</li></ul></li><li>Compatibility / migration behavior: <ul><li>The client must be rebuilt and re-embedded for any API change; <code>web/build</code> is baked into the binary at compile time (the <code>build-frontend</code> recipe in <code>Justfile</code> runs <code>bun run build</code>).</li><li><code>web/src/lib/types.ts</code> declares <code>SysInfo.used_disk</code>, which the server does not send; the dashboard computes disk usage from <code>total_disk</code>/<code>available_disk</code>, so the extra field is unused. Do not rely on it.</li><li>Dev mode proxies <code>/api/ws</code> (WebSocket) and <code>/api</code> to <code>http://localhost:12345</code> (<code>vite.config.ts</code>), so a backend must be running for <code>bun run dev</code>.</li></ul></li></ul><h2 id="forbidden-patterns-and-common-mistakes" tabindex="-1">Forbidden patterns and common mistakes <a class="header-anchor" href="#forbidden-patterns-and-common-mistakes" aria-label="Permalink to &quot;Forbidden patterns and common mistakes&quot;">​</a></h2><ul><li>Forbidden: hard-coding the backend host in the client; production is served from the same origin as the embedded assets.</li><li>Forbidden: putting the token in a query string or URL. It is sent as <code>Authorization</code> for HTTP and as a WebSocket subprotocol.</li><li>Forbidden: clearing <code>localStorage</code> directly instead of calling <code>clearAuthToken()</code>; the socket would stay authenticated.</li><li>Common mistake: assuming the UI is server-rendered. <code>ssr = false</code> and <code>prerender = false</code> mean every screen is client-only and <code>onMount</code> is where subscriptions belong.</li><li>Common mistake: assuming <code>currentPage</code> is 1-based. The videos store starts at <code>0</code>; the <code>me/*</code> pages pass <code>page + 1</code> because those Bilibili-backed endpoints are 1-based.</li><li>Common mistake: assuming a status value is a retry count. Values are <code>0</code> (not started), <code>1..3</code> (failures so far), <code>4</code> (retries exhausted, terminal failure), <code>7</code> (done); the UI shows 4 as 失败4次.</li><li>Common mistake: expecting <code>/video-sources</code> new subscriptions to be active immediately. Inserts are stored with <code>enabled: false</code>; the user must enable them.</li><li>Common mistake: expecting the settings page to validate cron locally. It only distinguishes numeric vs string; the server rejects invalid expressions with the Chinese message from <code>Config::check</code>.</li><li>Common mistake: expecting the notifier test to use the saved template. The ping request carries the current form notifier and the server forces a fresh render.</li></ul><h2 id="how-to-verify" tabindex="-1">How to verify <a class="header-anchor" href="#how-to-verify" aria-label="Permalink to &quot;How to verify&quot;">​</a></h2><ul><li>Type/lint/build (from <code>web/</code>): <code>bun run check</code> (svelte-check), <code>bun run lint</code> (<code>prettier --check . &amp;&amp; eslint .</code>), <code>bun run build</code>; the backend embeds <code>web/build</code>, so a successful binary build implies the directory exists.</li><li>Dev check: run the backend on <code>12345</code>, then <code>bun run dev</code>; confirm the proxy serves <code>http://localhost:5173</code> and that <code>/api/ws</code> connects using the token entered in <code>/settings</code>.</li><li>Auth check: open the app with no token → pages show 401 toasts; enter the token in <code>/settings</code> → config loads; click 退出认证 → token removed and the socket disconnects.</li><li>Live data check: open <code>/</code>, confirm CPU/memory charts update roughly every 2 seconds and the task card reflects a manual <code>POST /api/task/download</code>; open <code>/logs</code> and confirm the last 200 historical lines appear immediately, then live lines follow.</li><li>Filter check: apply status/validation/created-time filters on <code>/videos</code>, copy the URL, reopen it and confirm the same filtered view is restored.</li><li>Status editing check: in <code>/video/[id]</code> set a subtask to 已完成 or 未开始, save, reload and confirm the five-segment bar matches; run 重置 and confirm failed segments return to not-started.</li></ul>',15),c=[i];function a(n,r,l,u,h,p){return t(),o("div",null,c)}const v=e(s,[["render",a]]);export{m as __pageData,v as default};
